import sys

def find_root(parent):
    x = parent
    while parent[x] != x:
        x = parent[x]
    return x

def union(parent, rank, x, y):
    rootX = find_root(x)
    rootY = find_root(y)
    if rootX != rootY:
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1
    return rootX == rootY

def main():
    import sys
    input = sys.stdin.read().split()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n = int(input[index])
        k = int(input[index + 1])
        index += 2
        edges = []
        for _ in range(k):
            m = int(input[index])
            index += 1
            for _ in range(m):
                u = int(input[index])
                v = int(input[index + 1])
                edges.append((u, v))
                index += 2
        parent = list(range(n + 1))
        rank = [0] * (n + 1)
        tree_edges = []
        for u, v in edges:
            if union(parent, rank, u, v):
                tree_edges.append((u, v))
                if len(tree_edges) == n - 1:
                    break
        if len(tree_edges) == n - 1:
            results.append("YES")
            for u, v in tree_edges:
                results.append(f"{u} {v}")
        else:
            results.append("NO")
    print("\n".join(results))

main()
